package com.nokiaexperience.launcher;

import android.content.Context;
import android.graphics.Color;
import org.json.JSONObject;
import java.io.InputStream;

/** Optional, fail-safe visual bridge generated by Nokia Experience Studio. */
final class StudioRuntimeConfig {
    private int statusIconColor = Color.TRANSPARENT;
    private int accent = Color.TRANSPARENT;

    static StudioRuntimeConfig load(Context context) {
        StudioRuntimeConfig result = new StudioRuntimeConfig();
        try (InputStream stream = context.getAssets().open("studio/project.json")) {
            byte[] bytes = new byte[stream.available()];
            int read = stream.read(bytes);
            if (read <= 0) return result;
            JSONObject root = new JSONObject(new String(bytes, "UTF-8"));
            JSONObject theme = root.optJSONObject("theme");
            if (theme != null) {
                result.statusIconColor = parseColor(theme.optString("statusIconColor", ""));
                result.accent = parseColor(theme.optString("accent", ""));
            }
        } catch (Exception ignored) {
            // The Android build must remain usable when Studio has not exported a config.
        }
        return result;
    }

    int statusIconColor() { return statusIconColor; }
    int accent() { return accent; }

    private static int parseColor(String value) {
        try { return value == null || value.isEmpty() ? Color.TRANSPARENT : Color.parseColor(value); }
        catch (IllegalArgumentException ignored) { return Color.TRANSPARENT; }
    }
}
